            // refused is the reading the engine counts (`Engine.undecodablePayloads`); without
            // this call the payload is lost to the document and to the host alike.
            engine.notePayloadReading(event, reading: Self.payloadReading(of: reading))
        } catch {
            raiseExecutionError("_event could not be bound for '\(name)'", engine: engine)
        }
    }

    /// The engine's name for a rung the script engine reports: the two modules each declare the
    /// five readings, since the script engine does not depend on the runtime.
    private static func payloadReading(of reading: SceLua.PayloadReading) -> SceRuntime.PayloadReading {
        switch reading {
        case .absent: return .absent
        case .dom: return .dom
        case .structured: return .structured
        case .text: return .text
        case .undecodable: return .undecodable
        }
    }

    /// W3C SCXML 5.9.1: a `cond` that cannot be evaluated is false, and raises `error.execution`.
    private func evaluateGuard(_ condition: String, engine: Engine<Test279Policy>) -> Bool {
        var failed = false
        return evaluateCond(condition, of: "<transition>", failed: &failed, engine: engine)
    }

    /// W3C SCXML 4.3, 5.9.1: the same for the `cond` of an `<if>` or `<elseif>`, which also says that
    /// it failed, because the element that held it ends its block once the chain has run (§scxml-4.9).
    private func evaluateIfCond(_ condition: String, failed: inout Bool, engine: Engine<Test279Policy>) -> Bool {
        evaluateCond(condition, of: "<if>", failed: &failed, engine: engine)
    }

    private func evaluateCond(
        _ condition: String,
        of element: String,
        failed: inout Bool,
        engine: Engine<Test279Policy>
    ) -> Bool {
        do {
            return try scriptSession.evaluateCondition(condition, chunkName: "=cond")
        } catch {
            raiseExecutionError("a \(element) cond failed to evaluate", engine: engine)
            failed = true
            return false
        }
    }



    /// Enters one state (W3C SCXML 3.8): adds it to the configuration, runs its
    /// `<onentry>`, and its `<initial>` transition's content when its initial
    /// state is entered by default.
    public func executeEntryActions(_ state: Test279State, engine: Engine<Test279Policy>, isDefaultEntry: Bool) {
        switch state {
        default:
            break  // No entry actions
        }
    }

    /// Runs a `<history>`'s default transition content (W3C SCXML 3.10.2), after
    /// its parent's onentry (and after the parent's own `<initial>` content) when
    /// the history was taken with nothing recorded. The engine asks for it by the
    /// entry set's defaultHistoryContent answer; a history that restored what it
    /// recorded runs nothing.
    public func executeHistoryDefaultContent(_ history: HistoryID, engine: Engine<Test279Policy>) {
        // W3C SCXML 3.10.2: no <history> in this document has default content.
    }

    /// Exits one state (W3C SCXML 3.9): records its histories, runs its `<onexit>`,
    /// cancels its invocations and removes it from the configuration, in
    /// §scxml-D-exitStates's order.
    public func executeExitActions(_ state: Test279State, engine: Engine<Test279Policy>, configurationBeforeExit: [Test279State]) {
        // §scxml-D-exitStates orders one state's exit as onexit, then cancelInvoke,
        // then configuration.delete(s), so `In(s)` inside s's own handler is true:
        // the <onexit> switch comes first and the removal from the configuration
        // last.
        switch state {
        default:
            break  // No exit actions
        }
    }



    /// Appendix D selectTransitions, the half only this document can answer: the
    /// first of `state`'s own transitions, in document order, that `event` enables
    /// and whose guard holds. The engine walks the atomic states and their
    /// ancestors and keeps the ordered set; the null event asks for eventless
    /// transitions.
    public func firstEnabledTransition(
        _ state: Test279State,
        event: Test279Event,
        engine: Engine<Test279Policy>
    ) -> EnabledTransition<Test279State>? {
        switch state {
        case .s0:
            if event == .null {
                // W3C SCXML 5.9: cond="Var1 == 1" lowered to Lua at build time, run by the engine
                if (evaluateGuard("_scxml_eq(Var1, 1)", engine: engine)) {
                    return EnabledTransition(
                        source: state,
                        targets: [.state(.pass)],
                        transitionIndex: 0,
                        hasActions: false,
                        isInternal: false
                    )
                }
            }
            if event == .null {
                do {
                    return EnabledTransition(
                        source: state,
                        targets: [.state(.fail)],
                        transitionIndex: 1,
                        hasActions: false,
                        isInternal: false
                    )
                }
            }
        default:
            break
        }
        return nil
    }

